import java.util.List;
import java.util.stream.Collectors;

public class JoiningQuiz {
    public static void main(String[] args) {
        String result = List.of("A", "B", "C").stream()
            .collect(Collectors.joining("-", "[", "]"));
        System.out.println(result);
    }
}

import java.util.*;
import java.util.stream.Collectors;

public class GroupingQuiz {
    public static void main(String[] args) {
        Map<Integer, Long> result = List.of("hi", "hello", "go", "world", "ok")
            .stream()
            .collect(Collectors.groupingBy(String::length, Collectors.counting()));
        System.out.println(result.get(2));
        System.out.println(result.get(5));
    }
}

import java.util.*;
import java.util.stream.Collectors;

public class PartitionQuiz {
    public static void main(String[] args) {
        Map<Boolean, List<Integer>> result = List.of(1, 2, 3, 4, 5, 6)
            .stream()
            .collect(Collectors.partitioningBy(n -> n % 2 == 0));
        System.out.println(result.get(true).size());
        System.out.println(result.get(false).size());
    }
}
